from lib import *
S = SS('x62')
steps = [
    step("ThreadLocal 在 Reactor 里。主线程 TL.set(\"user-42\"):主线程直接读到 user-42;Mono.just(1).map(读 TL).block() 没有切线程,仍在 main 上,读到 user-42。一旦切线程就读不到:publishOn(parallel) 之后在 parallel-1 读到 null;Mono.delay(10ms) 之后在 parallel-2 读到 null;subscribeOn(boundedElastic) 的 Callable 里在 boundedElastic-1 读到 null。响应式链上的每个操作符可能在不同线程上执行,ThreadLocal 只对当前线程有效。", t=tl(S(1)), mark=lidx(S(1), 'parallel-1 读到 null', 'parallel-2 读到 null', 'boundedElastic-1 读到 null'), done=lidx(S(1), '主线程直接读', '没有切线程'), b=bars([['没切线程时读到', 1, 'user-42'], ['publishOn / delay / subscribeOn 后读到 null 的次数', 3, '3']], 3, done=[0], mark=[1]), kv=KV([['ThreadLocal', '只对当前线程有效'], ['切线程的操作符', 'publishOn、delay、subscribeOn 之后读不到'], ['原因', '一条响应式链会在多个线程上执行'], ['替代', 'Reactor Context']], ['ThreadLocal'])),
    step("Reactor Context 的写入、读取与方向。contextWrite 放在链的末尾,上游的 deferContextual 读到 alice;contextWrite 放在 deferContextual 的上游(之前):读到 (无)——Context 从订阅者向源头传,contextWrite 只影响它上游的操作符。两个 contextWrite 写同一个 key,最终上游看到离源头近的那个(inner)。Context 穿过 publishOn / subscribeOn 的线程切换:boundedElastic-1 读到 alice,Mono.delay 之后的 parallel-4 也读到 alice。Context 是不可变的:Context.of(\"k\", 1).put(\"k\", 2) 得到 2,原来的 Context 里还是 1。", t=tl(S(2)), mark=lidx(S(2), '(上游)= (无)'), done=lidx(S(2), '放在链的末尾', 'inner', '切线程', 'transformDeferredContextual', '不可变'), b=bars([['contextWrite 在链末尾:上游能读到(1=是)', 1, '是'], ['contextWrite 在上游之前:上游能读到(1=是)', 0, '否'], ['切线程后读到 alice(1=是)', 1, '是']], 1, done=[0, 2], mark=[1]), kv=KV([['contextWrite', '作用于它上游的操作符'], ['传递方向', '从订阅者往源头'], ['切线程', 'Context 随订阅关系走,不受影响'], ['不可变', '每次写都得到新的 Context']], ['contextWrite'])),
    step("Context 的边界。flatMap 的内层能读到外层的 Context(alice)。但在 flatMap 里手动 subscribe() 一条新链,读不到外层的 Context,得到 (无)——新的订阅没有继承。同一个 Mono 用两个不同的 Context 订阅,各读各的(A / B)。注意 cache():第一个订阅者(A)的结果被缓存下来,第二个订阅者(B)读到的也是 A。", t=tl(S(3)), mark=lidx(S(3), '手动 subscribe()', 'cache() 之后'), done=lidx(S(3), 'flatMap 内层读外层', '互不影响'), b=bars([['flatMap 内层读到外层 Context(1=是)', 1, '是'], ['手动 subscribe() 的新链读到(1=是)', 0, '否'], ['cache() 后第二个订阅者读到自己的(1=是)', 0, '否(读到 A)']], 1, done=[0], mark=[1, 2]), kv=KV([['flatMap 内层', '继承外层 Context'], ['手动 subscribe()', '新订阅,没有继承'], ['不同订阅者', '各有各的 Context'], ['cache()', '缓存了第一个订阅者算出来的值']], ['手动 subscribe()'])),
    step("让 ThreadLocal 跟着走。注册 ThreadLocalAccessor(micrometer context-propagation 1.2.1)之后:1) 什么都没配置:parallel-5 读到 null;2) 只注册了 accessor:null;3) 注册了 + 链尾 contextCapture(),但没开 Hook:仍然是 null。开了 Hooks.enableAutomaticContextPropagation() 之后:4) 没有 contextCapture 也读到 user-42(block() 订阅时捕获了主线程的值);5) 加 contextCapture():user-42;6) Mono.delay 之后和 subscribeOn(boundedElastic) 里都读到 user-42。7) 订阅线程上没有设置 TL 时:null。8) 线程池里的任务:普通提交读到 null,ContextSnapshot.captureAll().wrap(…) 包过的读到 user-42。要同时具备:注册 accessor + 开 Hook,缺一个都不行。", t=tl(S(4)), mark=lidx(S(4), '1) 什么都没配置', '2) 只注册了', '3) 注册了', '7) 订阅线程', '普通提交'), done=lidx(S(4), '4) 注册了', '5) 注册了', '6) 同上', 'ContextSnapshot'), b=bars([['没开 Hook 读到 user-42 的情形数', 0, '0/3'], ['开了 Hook 读到 user-42 的情形数', 3, '3/3 (4、5、6)'], ['线程池里 wrap 之后读到(1=是)', 1, '是']], 3, mark=[0], done=[1, 2]), kv=KV([['accessor + Hook', '缺一不可'], ['contextCapture()', '单独用不够,还要 Hook'], ['普通线程池', '要 ContextSnapshot.wrap 才能带上'], ['订阅线程没有值', '下游读到 null']], ['accessor + Hook'])),
]
A = mkartx('x62', 62, 'Spring,Reactor,Context,ThreadLocal,上下文传播,真实验证,动画演示',
    '实测响应式下的上下文传播:ThreadLocal 一旦经过 publishOn、delay、subscribeOn 就读到 null;Reactor Context 随订阅从订阅者向源头传,contextWrite 只影响上游,flatMap 内层继承而手动 subscribe() 的新链读不到,cache() 会把第一个订阅者的值带给后面的订阅者;注册 ThreadLocalAccessor 并开启 Hooks.enableAutomaticContextPropagation() 才能让 ThreadLocal 跟着走,缺一个都读到 null。',
    'WebFlux 里的 ThreadLocal(MDC、用户信息)为什么会丢?Reactor Context 怎么用、方向是什么?为什么手动 subscribe() 会丢上下文?怎样让 ThreadLocal 在响应式链里自动恢复?这篇用 Reactor 3.8.7 和 context-propagation 1.2.1 逐个验证。',
    [('null', 'publishOn / delay / subscribeOn 之后读 ThreadLocal 的结果'), ('(无)', 'contextWrite 放在上游之前、或在 flatMap 里手动 subscribe() 一条新链时读到的 Context'), ('2 者缺一', 'ThreadLocal 要自动恢复,必须同时注册 accessor 并开 Hook')],
    [('ThreadLocal 为什么丢', '<p>响应式链会在多个线程上执行,ThreadLocal 只在当前线程有效。</p>'),
     ('Context 的方向', '<p>从订阅者往源头传,contextWrite 只影响上游。</p>'),
     ('Context 的边界', '<p>手动 subscribe() 不继承;cache() 会把第一个订阅者的结果带给后面的订阅者。</p>'),
     ('自动恢复 ThreadLocal', '<p>注册 accessor 加开 Hook,线程池任务要 wrap。</p>')],
    steps,
    [ENV_X + '。用 reactor-core 3.8.7 与 io.micrometer:context-propagation 1.2.1 的单个 Java 程序,不依赖 Spring 容器;线程名 parallel-N 的序号随运行变化;第四节的 ThreadLocalAccessor 与 Hook 是全局的,按顺序一步步打开',
     '没有验证:Spring WebFlux 里 spring.reactor.context-propagation 属性与 Micrometer Tracing 的自动传播;MDC 的 ThreadLocalAccessor(micrometer-tracing 提供);Spring Security 的 ReactiveSecurityContextHolder;虚拟线程下的 ThreadLocal / ScopedValue;contextCapture 的性能开销;Reactor 的 Hooks.enableAutomaticContextPropagation 与 flatMap 内层线程切换的所有组合'],
    '上下文传播')
